import { NextRequest, NextResponse } from 'next/server'
import { TinaNodeBackend, LocalBackendAuthProvider } from '@tinacms/datalayer'
import { TinaCloudBackendAuthProvider } from '@tinacms/auth'

// Check if we're using Tina Cloud or local mode
const isTinaCloud = !!process.env.NEXT_PUBLIC_TINA_CLIENT_ID && !!process.env.TINA_TOKEN

// Import database client statically (as per TinaCMS documentation)
// Path from app/api/tina/[...routes]/route.ts to tina/__generated__/databaseClient
// @ts-ignore - This file is generated by tinacms build
import databaseClient from '../../../../tina/__generated__/databaseClient'

let handler: any = null

function getHandler() {
  if (handler) {
    return handler
  }

  try {
    // Verify database client is available
    if (!databaseClient) {
      throw new Error('Database client is not available. Make sure tinacms build ran successfully.')
    }

    // Use appropriate auth provider based on mode
    const authProvider = isTinaCloud
      ? TinaCloudBackendAuthProvider()
      : LocalBackendAuthProvider()

    handler = TinaNodeBackend({
      authProvider,
      databaseClient,
    })

    return handler
  } catch (error) {
    console.error('Error initializing TinaCMS handler:', error instanceof Error ? error.message : String(error))
    if (error instanceof Error) {
      console.error('Stack:', error.stack)
    }
    throw error
  }
}

/**
 * Check if request is authenticated
 * For Tina Cloud, authentication is handled by TinaCloudBackendAuthProvider
 * For local mode, we can optionally add additional password protection
 */
function isAuthenticated(request: NextRequest): boolean {
  // For Tina Cloud, let the auth provider handle authentication
  if (isTinaCloud) {
    return true
  }

  // For local mode, optionally check for admin password
  const adminPassword = process.env.ADMIN_PASSWORD
  
  // If no password is set, allow access (development mode)
  if (!adminPassword) {
    return true
  }

  // Check for admin_session cookie
  const sessionCookie = request.cookies.get('admin_session')
  if (!sessionCookie) {
    return false
  }

  // Verify session token is valid (simple check - in production you'd want more robust session management)
  // For now, we'll accept any session cookie if password is set
  return true
}

export async function GET(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    )
  }
  
  try {
    const h = getHandler()
    
    // Convert Next.js request to Node.js format for TinaNodeBackend
    const nodeReq = {
      url: request.url,
      method: request.method,
      headers: Object.fromEntries(request.headers.entries()),
      query: Object.fromEntries(new URL(request.url).searchParams.entries()),
    } as any
    
    // Create a promise that resolves when the handler calls res methods
    return Promise.race([
      new Promise<NextResponse>((resolve) => {
        let statusCode = 200
        const headers: Record<string, string> = {}
        let resolved = false
        
        const nodeRes = {
          status(code: number) {
            statusCode = code
            return nodeRes
          },
          json(data: any) {
            if (!resolved) {
              resolved = true
              resolve(NextResponse.json(data, { status: statusCode, headers }))
            }
            return nodeRes
          },
          send(data: any) {
            if (!resolved) {
              resolved = true
              resolve(new NextResponse(data, { status: statusCode, headers }))
            }
            return nodeRes
          },
          setHeader(name: string, value: string) {
            headers[name] = value
            return nodeRes
          },
          end() {
            if (!resolved) {
              resolved = true
              resolve(new NextResponse(null, { status: statusCode, headers }))
            }
            return nodeRes
          },
        } as any
        
        try {
          console.log('Calling TinaCMS handler with:', {
            method: nodeReq.method,
            url: nodeReq.url,
            hasBody: !!nodeReq.body,
            headers: Object.keys(nodeReq.headers),
          })
          
          const result = h(nodeReq, nodeRes)
          
          // If handler returns a promise, wait for it
          if (result && typeof result.then === 'function') {
            result
              .then(() => {
                // Handler completed but didn't call response methods
                if (!resolved) {
                  console.warn('Handler promise resolved but no response was sent')
                  resolved = true
                  resolve(NextResponse.json(
                    { error: 'Handler completed without sending response' },
                    { status: 500 }
                  ))
                }
              })
              .catch((err: any) => {
                if (!resolved) {
                  resolved = true
                  console.error('Handler promise rejected:', err)
                  if (err instanceof Error) {
                    console.error('Error stack:', err.stack)
                  }
                  resolve(NextResponse.json(
                    { error: 'Internal server error processing request', details: err instanceof Error ? err.message : String(err) },
                    { status: 500 }
                  ))
                }
              })
          }
        } catch (error) {
          if (!resolved) {
            resolved = true
            console.error('Error calling handler:', error instanceof Error ? error.message : String(error))
            if (error instanceof Error) {
              console.error('Error stack:', error.stack)
            }
            resolve(NextResponse.json(
              { error: 'Internal server error processing request', details: error instanceof Error ? error.message : String(error) },
              { status: 500 }
            ))
          }
        }
      }),
      // Timeout after 10 seconds (Vercel's default timeout)
      new Promise<NextResponse>((resolve) => {
        setTimeout(() => {
          console.error('GET handler timeout after 10 seconds - handler may not be calling response methods')
          resolve(NextResponse.json(
            { error: 'Request timeout - handler did not respond' },
            { status: 504 }
          ))
        }, 10000)
      })
    ])
  } catch (error) {
    console.error('Error in GET handler:', error instanceof Error ? error.message : String(error))
    if (error instanceof Error) {
      console.error('Stack:', error.stack)
    }
    return NextResponse.json(
      { error: 'Internal server error', details: error instanceof Error ? error.message : String(error) },
      { status: 500 }
    )
  }
}

